#!/usr/bin/env python
"""External baselines next to Opsis: CLAM-SB (scripts/57), PRISM2 zero shot / mismatch /
linear probe (scripts/58), CellViT++ NuCLS heads (scripts/59), against the slide decoder on the v2 questions (runs jev_v2_op_s0..2) and
on the v1 questions (runs slide_jev_s0..2) on the same test slides.
    python scripts/60_collect_baselines.py [--out results/collected/RESULTS_baselines_tables.md]"""
import argparse, glob, json, os
import numpy as np
from opsis import paths

ap = argparse.ArgumentParser(); ap.add_argument("--out", default=None); a = ap.parse_args(); R = paths.RUNS
def load(name):
    f = f"{R}/{name}/metrics_test.json"; return json.load(open(f)) if os.path.exists(f) else None
def agg(names, op, key):
    v = [m["per_op"][op][key] for n in names if (m := load(n)) and op in m["per_op"] and m["per_op"][op].get(key) is not None]
    return (float(np.mean(v)), float(np.std(v)), len(v)) if v else None
def fmt(t, d=3): return "" if t is None else (f"{t[0]:.{d}f}" if t[2] == 1 else f"{t[0]:.{d}f} ± {t[1]:.{d}f}")
TASKS = ["er_positive", "pr_positive", "her2_positive", "pam50", "histologic_grade", "histologic_type", "in_situ_present", "lvi_present", "necrosis_present", "multifocal", "lcis_present", "calcifications",
         "dcis_comedo_necrosis", "nuclear_grade", "tubule_score", "pleomorphism_score", "mitotic_score", "dcis_grade"]
cols = {"Opsis-S breast v1 (3 seeds)": ["slide_jev_s0", "slide_jev_s1", "slide_jev_s2"], "Opsis-S breast (3 seeds)": ["jev_v2_op_s0", "jev_v2_op_s1", "jev_v2_op_s2"], "Opsis-S breast text+op": ["jev_v2_text_s0"],
        "CLAM-SB (seeds)": None, "ABMIL (seeds)": None, "TITAN probe": ["titan_brca_probe"], "PRISM2 probe": ["prism2_brca_probe"], "TITAN zero shot": ["titan_brca_zeroshot"], "PRISM2 zero shot": ["prism2_zeroshot"], "PRISM2 mismatched slide": ["prism2_zeroshot_mismatch"]}
lines = ["# External baselines on our test slides (generated by scripts/60_collect_baselines.py)", "", "Accuracy (majority) with AUROC where defined; test split of the patient level split seed 0 (170 slides). CLAM-SB: repository defaults, full tile bags of the Virchow2 cache. ABMIL: the gated attention MIL of Ilse et al. 2018 (CLAM-SB's network without the instance clustering loss, scripts/57 --model abmil), full bags. PRISM2: Virchow2 class tokens sliced from the 256 px cache (the model expects 224 px), yes/no scoring for binary operators, multiple choice generation otherwise (accuracy only). Probes (scripts/88): logistic regression on the released TITAN slide embeddings and on the PRISM2 base embeddings, every field, C chosen on val. TITAN zero shot: text prompts per field (scripts/88).", ""]
hdr = "| operator | maj | " + " | ".join(cols) + " |"; lines += [hdr, "|" + "---|" * (hdr.count("|") - 1)]
for op in TASKS:
    cells = []; maj = None
    for g, names in cols.items():
        if g in ("CLAM-SB (seeds)", "ABMIL (seeds)"): names = sorted({os.path.basename(p) for p in glob.glob(f"{R}/{'clam' if g.startswith('CLAM') else 'abmil'}_{op}_s*") if "smoke" not in p})
        key_op = op
        acc, au = agg(names, key_op, "acc"), agg(names, key_op, "auroc")
        for n in names:
            m = load(n)
            if m and key_op in m["per_op"] and maj is None: maj = m["per_op"][key_op]["majority_acc"]
        cells.append("" if acc is None else (fmt(acc) + (f" / AUROC {fmt(au)}" if au else "")))
    if any(cells): lines.append(f"| {op} | {'' if maj is None else f'{maj:.2f}'} | " + " | ".join(cells) + " |")
# CellViT++ NuCLS heads (classification on ground truth cells, and the detection + classification pipeline)
rows = []
for d in sorted(glob.glob(f"{R}/cellvit_nucls/*/*/test_results/inference_results.json")):
    b = d.split("/")[-4]; j = json.load(open(d)); g = j["classifier"]["global"]; ct = j["pipeline"]["detection_scores_tia"]["cell_types"]; det = j["pipeline"]["detection_scores_tia"]["binary"]
    rows.append(f"| CellViT++ {b} | {g['Acc']:.3f} | {g['F1']:.3f} | {g.get('Auroc', float('nan')):.3f} | {det['f1']:.3f} | " + " / ".join(f"{ct[k]['f1']:.2f}" for k in ("tumor_any", "nonTIL_stromal", "sTIL", "other_nucleus") if k in ct) + " |")
if rows:
    lines += ["", "## NuCLS super classes on our test patients: CellViT++ heads vs Opsis-S", "", "| model | acc on GT cells | F1 | AUROC | detection F1 | pipeline F1 tumor / stromal / sTIL / other |", "|---|---|---|---|---|---|"] + rows
    ours = load("jevpool_dens_v2_s0") or load("jevpool_all_v2_s0")
    if ours and "cell_super" in ours["per_op"]: lines.append(f"| Opsis-S (oracle locations, {'density aux' if load('jevpool_dens_v2_s0') else 'jevpool'}) | {ours['per_op']['cell_super']['acc']:.3f} | {ours['per_op']['cell_super']['macro_f1']:.3f} | | | |")
# CellViT++ heads on the seven NuCLS main classes (scripts/59 with LEVEL=main), the comparable of the cell class question; used by scripts/97
MAIN7 = ("tumor_nonMitotic", "tumor_mitotic", "nonTILnonMQ_stromal", "macrophage", "lymphocyte", "plasma_cell", "other_nucleus"); rows = []
for d in sorted(glob.glob(f"{R}/cellvit_nucls_main/*/*/test_results/inference_results.json")):
    b = d.split("/")[-4]; j = json.load(open(d)); g = j["classifier"]["global"]; ct = j["pipeline"]["detection_scores_tia"]["cell_types"]; det = j["pipeline"]["detection_scores_tia"]["binary"]
    rows.append(f"| CellViT++ {b} | {g['Acc']:.3f} | {g['F1']:.3f} | {g.get('Auroc', float('nan')):.3f} | {det['f1']:.3f} | " + " / ".join(f"{ct[k]['f1']:.2f}" for k in MAIN7 if k in ct) + " |")
if rows:
    lines += ["", "## NuCLS main classes on our test patients: CellViT++ heads", "", "| model | acc on GT cells | F1 | AUROC | detection F1 | pipeline F1 " + " / ".join(MAIN7) + " |", "|---|---|---|---|---|---|"] + rows
# blank image control on the final field question set (scripts/40 --qset questions_final --blank-image): the same typed questions with a blank canvas
BF = {"Qwen3-VL-8B": ("zs_qwen3vl8b_final", "zs_qwen3vl8b_blank_final"), "Patho-R1-7B": ("zs_pathor1_7b_final", "zs_pathor1_7b_blank_final")}; rows = []
for name, (ri, rb) in BF.items():
    im, bl = load(ri), load(rb)
    if not (im and bl): continue      # the control of this model has not finished
    tot = lambda r: sum(v["acc"] * v["n"] for v in r["per_op"].values()) / sum(v["n"] for v in r["per_op"].values()); n = sum(v["n"] for v in im["per_op"].values())
    assert n == sum(v["n"] for v in bl["per_op"].values()), (name, "the two runs answered different questions")
    rows.append(f"| {name} | all questions | {n} | {tot(im):.3f} | {tot(bl):.3f} | {tot(im) - tot(bl):+.3f} |")
    for op in ("cell_super", "cell_main", "cell_area_bin", "compare_regions", "dominant_tissue", "stil_score_bin"):
        x, y = im["per_op"][op], bl["per_op"][op]; rows.append(f"| {name} | {op} | {x['n']} | {x['acc']:.3f} | {y['acc']:.3f} | {x['acc'] - y['acc']:+.3f} |")
if rows: lines += ["", "## Blank image control on the final field question set", "", "| model | operator | n | with the canvases | blank image | difference |", "|---|---|---|---|---|---|"] + rows
# zero shot VLMs on the FOV questions (scripts/40), with the blank image control as the language prior; used by scripts/97 and 93c
ZS = {"Opsis-S (jevpool_dens_v2_s0)": "jevpool_dens_v2_s0", "Opsis-V (vlm_all_v2_s0)": "vlm_all_v2_s0", "Qwen3-VL-8B zero shot": "zs_qwen3vl8b", "Qwen3-VL-8B zero shot, blank image": "zs_qwen3vl8b_blank", "Patho-R1-7B zero shot": "zs_pathor1_7b", "Patho-R1-7B zero shot, blank image": "zs_pathor1_7b_blank"}
M = {k: load(v) for k, v in ZS.items() if load(v)}
if M:
    ops = ["cell_super", "cell_main", "cell_area_bin", "cell_tissue", "count_bin", "present", "cell_frac_bin", "more_cells", "tissue_frac_bin", "dominant_tissue", "compare_regions", "count_in_compartment_bin", "tils_location"]
    lines += ["", "## Zero shot VLMs on the FOV questions (NuCLS v2 test, accuracy / NLL; the blank image rows are the language prior)", "", "| operator | maj | " + " | ".join(M) + " |", "|" + "---|" * (len(M) + 2)]
    for op in ops:
        cells = []; maj = None
        for m in M.values():
            r = m["per_op"].get(op)
            if r is None: cells.append(""); continue
            maj = maj or r["majority_acc"]; cells.append(f"{r['acc']:.3f} / {r['nll']:.2f}")
        lines.append(f"| {op} | {'' if maj is None else f'{maj:.2f}'} | " + " | ".join(cells) + " |")
    lines.append("| test NLL (all) | | " + " | ".join(f"{m['test_nll']:.3f}" for m in M.values()) + " |")
    lines += ["", "PRISM2 mismatched slide control (each slide replaced by another slide of the test set, probe of arXiv 2610.26805): ER 0.605 (AUROC 0.50) against 0.778 (AUROC 0.81) with the right slide, grade 0.331 against 0.697, LVI 0.600 against 0.727. PRISM2 zero shot therefore reads the slide; the published SlideChat probe (74.8 with the slide, 74.4 without) does not transfer to it."]
txt = "\n".join(lines); print(txt)
if a.out: open(a.out, "w").write(txt + "\n")
